The connected media tools can’t generate anything with the account at **0 credits**. The closest I can provide here is a **single, self-contained HTML animatic**: a 30-second, 16:9 illustrated version with all four shots, matching title cards, animated rain, synthesized rain sound, and browser-spoken dialogue.

**Save the code below as `Walk Anyway.html`, then open it and click Play.** It’s a browser animation, **not an MP4**. The dialogue uses your browser’s available voice; I haven’t been able to test playback here.

```html
<!doctype html>
<html lang="en">
<meta charset="utf-8">
<title>Walk Anyway</title>
<style>
  * { box-sizing: border-box }
  body {
    margin: 0; background: #080b10; color: white;
    font: 15px system-ui; min-height: 100vh;
    display: grid; place-content: center; gap: 16px;
  }
  canvas { width: min(96vw, 1120px); aspect-ratio: 16/9; background: black }
  footer { display: flex; align-items: center; gap: 18px }
  button {
    background: white; color: #111; border: 0;
    border-radius: 5px; padding: 10px 24px; cursor: pointer;
  }
  span { color: #adb7c4 }
</style>
<canvas id="film" width="1280" height="720"
        aria-label="Walk Anyway, an illustrated short film"></canvas>
<footer>
  <button id="play">Play</button>
  <span id="status">30 seconds · Illustrated animatic · Sound on</span>
</footer>
<script>
const canvas = document.querySelector("#film");
const c = canvas.getContext("2d");
const button = document.querySelector("#play");
const status = document.querySelector("#status");
let running = false, start = 0, spoken = false;
let audio, rainGain, rainSource, frame;

function rect(x,y,w,h,color) {
  c.fillStyle=color; c.fillRect(x,y,w,h);
}
function line(x,y,x2,y2,color,width=2) {
  c.strokeStyle=color; c.lineWidth=width;
  c.beginPath(); c.moveTo(x,y); c.lineTo(x2,y2); c.stroke();
}
function oval(x,y,rx,ry,color) {
  c.fillStyle=color; c.beginPath();
  c.ellipse(x,y,rx,ry,0,0,Math.PI*2); c.fill();
}
function shape(points,color) {
  c.fillStyle=color; c.beginPath();
  points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));
  c.closePath(); c.fill();
}
function title() {
  rect(0,0,1280,720,"#000");
  c.fillStyle="#fff"; c.textAlign="center";
  c.font="500 62px Arial, sans-serif";
  c.fillText("WALK ANYWAY",640,382);
}
function backdrop(t) {
  let sky=c.createLinearGradient(0,0,0,720);
  sky.addColorStop(0,"#080e1b");
  sky.addColorStop(1,"#263746");
  rect(0,0,1280,720,sky);
  for(let i=0;i<12;i++) {
    const x=i*119-35, h=160+(i*47)%140;
    rect(x,340-h,100,h,"#101a27");
    for(let j=0;j<5;j++)
      if((i+j)%3===0)
        rect(x+18+j*13,245-(i*17)%90,5,14,"#bba371");
  }
  rect(0,440,1280,280,"#17232f");
  for(let i=0;i<55;i++) {
    const x=(i*173)%1280, y=456+(i*43)%250;
    rect(x,y,18+(i*29)%100,2,i%3?"#344755":"#76644c");
  }
  line(1130,160,1130,455,"#576674",7);
  oval(1128,164,29,8,"#f6d28d");
  let glow=c.createRadialGradient(1128,210,0,1128,210,330);
  glow.addColorStop(0,"#eabf6625"); glow.addColorStop(1,"#eabf6600");
  rect(790,0,490,550,glow);
  // Bus shelter: roof, glass panels, bench and bus-stop sign.
  rect(185,210,465,16,"#566778");
  rect(201,226,9,240,"#667788");
  rect(622,226,9,240,"#667788");
  rect(213,235,400,207,"#9bb8c013");
  line(415,230,415,442,"#59717e",3);
  rect(231,407,350,9,"#6a7479");
  line(254,416,254,462,"#586370",5);
  line(550,416,550,462,"#586370",5);
  line(695,230,695,467,"#6f808c",5);
  rect(676,220,39,49,"#cad7dc");
  rect(685,231,21,15,"#274558");
  oval(689,251,3,3,"#274558");
  oval(703,251,3,3,"#274558");
}
function woman(x,y,s=1,back=false,walk=0,smile=false) {
  c.save(); c.translate(x,y); c.scale(s,s);
  oval(0,4,43,9,"#060c1466");
  const step=Math.sin(walk)*7;
  line(-14,-56,-15+step,-9,"#182532",12);
  line(14,-56,15-step,-9,"#182532",12);
  rect(-25+step,-16,22,17,"#e5bf35");
  rect(4-step,-16,22,17,"#e5bf35");
  shape([[-24,-155],[24,-155],[35,-53],[-34,-53]],"#b52b3b");
  line(-25,-142,-38,-78,"#a42333",13);
  line(25,-142,35,-84,"#cb3948",13);
  line(0,-148,0,-61,"#e8596066",2);
  rect(-7,-169,14,19,"#d9ac98");
  oval(0,-191,23,30,"#d5d9de");
  rect(-24,-193,48,29,"#c8cfd8");
  if(!back) {
    oval(0,-187,17,24,"#dfb7a4");
    shape([[-22,-203],[4,-220],[24,-202],[23,-188],
           [10,-202],[-20,-187]],"#e0e5eb");
    oval(-6,-187,1.4,1.5,"#28323c");
    oval(7,-187,1.4,1.5,"#28323c");
    c.strokeStyle="#864e4e"; c.lineWidth=1.6;
    c.beginPath(); c.moveTo(-5,-174);
    c.quadraticCurveTo(1,smile?-167:-173,7,-174); c.stroke();
  }
  c.restore();
}
function man(x,y,s=1,back=false,walk=0,talking=false) {
  c.save(); c.translate(x,y); c.scale(s,s);
  oval(0,4,43,9,"#060c1466");
  const step=Math.sin(walk)*6;
  line(-13,-53,-14+step,-8,"#192025",13);
  line(13,-53,15-step,-8,"#192025",13);
  rect(-25+step,-10,24,12,"#111821");
  rect(3-step,-10,24,12,"#111821");
  shape([[-29,-147],[25,-147],[35,-45],[-35,-45]],"#426254");
  line(-27,-134,-36,-78,"#365346",14);
  line(25,-133,37,-106,"#527463",13);
  line(37,-106,46,-125,"#527463",12);
  oval(46,-126,6,8,"#cba28b");
  rect(-7,-161,14,20,"#cba28b");
  oval(0,-182,24,29,"#969d9f");
  if(!back) {
    oval(0,-181,19,24,"#cfa991");
    shape([[-19,-185],[-16,-162],[0,-149],[18,-165],
           [19,-184],[10,-174],[-10,-174]],"#abb0af");
    oval(-7,-184,1.5,1.5,"#263036");
    oval(7,-184,1.5,1.5,"#263036");
    oval(0,-169,5,talking?3.5:1,"#4f4441");
  }
  c.restore();
}
function umbrella(x,y,s=1) {
  c.save(); c.translate(x,y); c.scale(s,s);
  line(0,-145,0,-325,"#9ba5ad",3);
  c.fillStyle="#080e17"; c.beginPath();
  c.moveTo(-116,-249);
  c.quadraticCurveTo(-86,-317,0,-322);
  c.quadraticCurveTo(86,-317,116,-249);
  c.quadraticCurveTo(86,-262,57,-249);
  c.quadraticCurveTo(28,-263,0,-249);
  c.quadraticCurveTo(-28,-263,-57,-249);
  c.quadraticCurveTo(-86,-262,-116,-249);
  c.fill();
  line(0,-322,-57,-251,"#283441",1);
  line(0,-322,57,-251,"#283441",1);
  line(0,-330,0,-321,"#a3acb6",2);
  c.restore();
}
function rain(t) {
  c.save();
  for(let i=0;i<310;i++) {
    const x=((i*97.31-t*98)%1360+1360)%1360-40;
    const y=(i*73.79+t*(380+i%90))%760-20;
    line(x,y,x-7,y+19,"#bdd6e233",1);
  }
  c.restore();
}
function scene(t) {
  if(t<2 || t>=28) { title(); return; }
  const close=t>=16 && t<22;
  c.save();
  if(close) {
    c.translate(640,375); c.scale(2.6,2.6);
    c.translate(-660,-370);
  }
  backdrop(t);
  if(t<9) {
    woman(555,478,1,false,0,false);
  } else if(t<16) {
    const p=Math.min(1,(t-9)/5.5);
    const x=1030-325*p;
    woman(555,478,1,false,0,false);
    man(x,478,1,false,p<1?t*8:0,false);
    umbrella(x-5,478);
  } else if(t<22) {
    woman(600,478,1,false,0,t>18.5);
    man(710,478,1,false,0,t>17 && t<18.5);
    umbrella(665,478);
  } else {
    const p=(t-22)/6, s=1-p*.37;
    const x=650+p*115, y=478-p*45;
    woman(x-47*s,y,s,true,t*7);
    man(x+45*s,y,s,true,t*7+.7);
    umbrella(x,y,s);
  }
  c.restore();
  rain(t);
  // Subtle vignette.
  let v=c.createRadialGradient(640,330,180,640,360,760);
  v.addColorStop(0,"#0000"); v.addColorStop(1,"#0008");
  rect(0,0,1280,720,v);
}
function startRain() {
  const AC=window.AudioContext||window.webkitAudioContext;
  if(!AC) return;
  audio=new AC(); audio.resume();
  const buffer=audio.createBuffer(1,audio.sampleRate*3,audio.sampleRate);
  const data=buffer.getChannelData(0);
  for(let i=0;i<data.length;i++) data[i]=(Math.random()*2-1);
  rainSource=audio.createBufferSource();
  rainSource.buffer=buffer; rainSource.loop=true;
  const filter=audio.createBiquadFilter();
  filter.type="lowpass"; filter.frequency.value=4200;
  rainGain=audio.createGain(); rainGain.gain.value=0;
  rainSource.connect(filter); filter.connect(rainGain);
  rainGain.connect(audio.destination); rainSource.start();
}
function speak() {
  if(!("speechSynthesis" in window)) return;
  const u=new SpeechSynthesisUtterance("You came back.");
  u.lang="en-US"; u.rate=.78; u.pitch=.72; u.volume=.95;
  const voices=speechSynthesis.getVoices();
  const voice=voices.find(v=>/^en/i.test(v.lang)
    && /male|david|daniel|george|james/i.test(v.name));
  if(voice) u.voice=voice;
  speechSynthesis.speak(u);
}
function stop() {
  running=false; cancelAnimationFrame(frame);
  if(rainSource) { try { rainSource.stop(); } catch(e) {} }
  if(audio) audio.close();
  if("speechSynthesis" in window) speechSynthesis.cancel();
  button.textContent="Replay";
}
function tick(now) {
  if(!running) return;
  const t=Math.min(30,(now-start)/1000);
  scene(t);
  if(rainGain)
    rainGain.gain.setTargetAtTime(t>=2&&t<28?.11:0,audio.currentTime,.08);
  if(t>=17 && !spoken) { spoken=true; speak(); }
  status.textContent=t.toFixed(1)+" / 30 seconds";
  if(t>=30) {
    stop(); title();
    status.textContent="Finished · Replay to loop";
    return;
  }
  frame=requestAnimationFrame(tick);
}
button.onclick=()=>{
  if(running) { stop(); title(); return; }
  spoken=false;
  if("speechSynthesis" in window) speechSynthesis.cancel();
  startRain(); running=true; start=performance.now();
  button.textContent="Stop"; frame=requestAnimationFrame(tick);
};
title();
</script>
</html>
